def compute_Last_Digit(a, b):
    # The quotient factorial(b) // factorial(a) = product of integers from a+1 to b
    # We want the last digit of this product.
    # If a == b, the product is empty, so return 1 (since factorial(b)//factorial(b) =1)
    if a == b:
        return 1
    product_mod_10 = 1
    for x in range(a+1, b+1):
        product_mod_10 = (product_mod_10 * (x % 10)) % 10
        # If product_mod_10 becomes 0, no need to continue
        if product_mod_10 == 0:
            return 0
    return product_mod_10

