def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # If all digits are '9', next palindrome is 10...01 with length+1
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    def mirror_left_to_right(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    # Start by constructing a palindrome by mirroring left half to right half
    half_len = (length + 1) // 2  # middle included in left half if odd length
    left_half = s[:half_len]

    # Construct palindrome candidate by mirroring left_half
    palindrome = mirror_left_to_right(left_half, length % 2 != 0)

    if int(palindrome) > num:
        return int(palindrome)

    # If palindrome is not strictly greater, increment the left half and mirror again
    # Increment left half as integer
    left_num = int(left_half)
    left_num += 1
    left_half = str(left_num)

    # If length changed because of increment (e.g. 999->1000), adjust palindrome accordingly
    if len(left_half) > half_len:
        # This happens if increment causes carry beyond half_len (e.g. 999 -> 1000)
        # New palindrome is '1' + zeros + '1' with length+1
        return int('1' + ('0' * (length - 1)) + '1')

    palindrome = mirror_left_to_right(left_half, length % 2 != 0)
    return int(palindrome)

def next_power_of_2(n: int) -> int:
    if n <= 0:
        return 1
    # Check if n is already a power of 2
    if (n & (n - 1)) == 0:
        return n
    power = 1
    while power < n:
        power <<= 1
    return power

