def get_total_number_of_sequences(n: int, max_element: int) -> int:
    # dp[i][x]: number of sequences of length i ending with element x
    # since the first element can be any integer from 1 to max_element

    if n == 1:
        return max_element  # all single elements sequences

    dp = [0] * (max_element + 1)
    # For i=1, sequences of length 1, count = 1 for each element
    for x in range(1, max_element + 1):
        dp[x] = 1

    for length in range(2, n + 1):
        new_dp = [0] * (max_element + 1)
        # We want to find sequences of length length ending with y
        # where y >= 2 * previous element x.
        # For each y, sum over dp[x] for all x <= y//2
        # To do this efficiently, precompute prefix sums of dp

        prefix_sum = [0] * (max_element + 2)
        for x in range(1, max_element + 1):
            prefix_sum[x] = prefix_sum[x-1] + dp[x]

        for y in range(1, max_element + 1):
            limit = y // 2
            if limit >= 1:
                new_dp[y] = prefix_sum[limit]
            else:
                new_dp[y] = 0
        dp = new_dp

    return sum(dp[1:])

