def permute_string(s):
    def backtrack(path, used):
        if len(path) == len(s):
            print("".join(path))
            return
        for i in range(len(s)):
            if used[i]:
                continue
            used[i] = True
            path.append(s[i])
            backtrack(path, used)
            path.pop()
            used[i] = False

    used = [False] * len(s)
    backtrack([], used)

