def find_Max(nums):
    if not nums:
        return None  # or raise an error if empty array is invalid input

    left, right = 0, len(nums) - 1

    # If array is not rotated (sorted ascending), max is last element
    if nums[left] < nums[right]:
        return nums[right]

    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid

    # left is now the index of the minimum element
    # maximum element is one before minimum (considering wrap)
    max_index = (left - 1) % len(nums)
    return nums[max_index]

