def next_smallest_palindrome(num: int) -> int:
    # Handle small numbers: palindrome smaller than num must be < num
    # For num <= 0, no smaller palindrome (negative or zero) is generally considered
    # but negative palindromes are not standard, return -1 as no smaller palindrome
    if num <= 0:
        return -1

    # If num is 1, the next smaller palindrome is 0
    if num == 1:
        return 0

    s = str(num)

    # Helper to check if a string is palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # Helper to create palindrome by mirroring left half to right
    def make_palindrome(left: str, odd_len: bool) -> int:
        if odd_len:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    length = len(s)
    odd_len = (length % 2 != 0)
    left = s[: (length + 1) // 2]

    # Construct palindrome from left half (mirror)
    pal = make_palindrome(left, odd_len)
    if pal >= num:
        # Decrement the left half and then mirror again
        # Convert left to int, decrement, handle leading zeros
        left_num = int(left) - 1
        if left_num == 0:
            # For cases like 1000, decrement left half leads to 0, 
            # which means palindrome of smaller length all 9's
            return int("9" * (length - 1)) if length > 1 else 0
        left_str = str(left_num)

        # If length of left_str is less than original left length (e.g. 100 -> 99),
        # it means the palindrome length should decrease by 1 
        # (e.g. 1000 -> 999)
        if len(left_str) < len(left):
            return int("9" * (length - 1))

        pal = make_palindrome(left_str, odd_len)

    # If palindrome found is smaller than num, return it
    if pal < num:
        return pal

    # If no palindrome smaller found (should not happen), handle special case
    # (e.g. num=10, palindrome from left is 11, decrement left to 0 triggers above)
    # fallback:
    return int("9" * (length - 1)) if length > 1 else 0

