    """Return the least common multiple of two positive integers a and b."""
    if a <= 0 or b <= 0:
        raise ValueError("Both numbers must be positive integers.")

    def gcd(x: int, y: int) -> int:
        while y:
            x, y = y, x % y
        return x

    return a * b // gcd(a, b)

