def compute_Last_Digit(a, b):
    if a > b:
        # Compute last digit of a!/b! = product of integers from b+1 to a
        start, end = b + 1, a
    else:
        # Treat as if a < b and compute last digit of product from a+1 to b
        start, end = a + 1, b

    last_digit = 1
    for num in range(start, end + 1):
        last_digit = (last_digit * (num % 10)) % 10
        # Early stop if last_digit is 0, since multiplication by any number will keep 0
        if last_digit == 0:
            break
    return last_digit

