def find_solution(a: int, b: int, n: int):
    # We want non-negative integers x,y >= 0 such that a*x + b*y = n.
    # If no such solution exists, return None.
    # Otherwise return (x, y).

    # Handle trivial cases:
    if n < 0:
        return None
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # Try all possible x from 0 up to n//a (max x with a*x <= n)
    max_x = n // a
    for x in range(max_x + 1):
        remainder = n - a * x
        if remainder < 0:
            break
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
    return None

