def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 1
    for v in d.values():
        if isinstance(v, dict):
            depth = 1 + dict_depth(v)
        elif isinstance(v, (list, tuple)):
            # For lists/tuples, check their elements at the same depth (do not add depth)
            depth = 1 + max((dict_depth(i) for i in v), default=0)
        else:
            depth = 1
        if depth > max_depth:
            max_depth = depth
    return max_depth

def remove_column(matrix, index):
    if not matrix:
        return []
    row_length = len(matrix[0])
    if not all(len(row) == row_length for row in matrix):
        raise ValueError("All rows must have the same length before removal.")
    if not (0 <= index < row_length):
        raise IndexError("Index out of range.")
    result = []
    for row in matrix:
        new_row = row[:index] + row[index+1:]
        result.append(new_row)
    new_length = len(result[0]) if result else 0
    if not all(len(row) == new_length for row in result):
        raise ValueError("All rows must have the same length after removal.")
    return result

