def smallest_missing(arr, low, high):
    # Find the smallest non-negative integer missing from arr[low:high+1]
    # arr is sorted, distinct, non-negative integers
    # The returned integer must be the smallest non-negative integer missing from that subarray

    if low > high:
        return 0  # empty range, 0 is smallest missing

    # If the subarray starts with a number > 0, then 0 is missing
    if arr[low] > 0:
        return 0

    left, right = low, high
    while left <= right:
        mid = (left + right) // 2
        # The expected value at position mid if no numbers missing from arr[low]
        expected = arr[low] + (mid - low)
        if arr[mid] == expected:
            # No missing number before mid, search right
            left = mid + 1
        else:
            # Missing number is at or before mid
            right = mid - 1

    # After binary search, left is the index where missing number should be
    # Missing number is arr[low] + (left - low)
    return arr[low] + (left - low)

