def find_Max(arr, start, end):
    # Handle empty array case
    if start > end:
        raise ValueError("Invalid input: start index cannot be greater than end index.")
    # Base case: only one element
    if start == end:
        return arr[start]
    # Base case: two elements, return the max
    if end == start + 1:
        return max(arr[start], arr[end])

    mid = (start + end) // 2

    # Check if mid element is greater than next element, mid is max
    if mid < end and arr[mid] > arr[mid + 1]:
        return arr[mid]
    # Check if mid element is smaller than previous element, previous is max
    if mid > start and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]

    # Decide which half to search
    if arr[start] >= arr[mid]:
        # Max must be in left half
        return find_Max(arr, start, mid - 1)
    else:
        # Max must be in right half
        return find_Max(arr, mid + 1, end)

