def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        return num + 2  # e.g. 9 -> 11, 99 -> 101, 999 -> 1001

    def mirror_left_to_right(s):
        half = length // 2
        if length % 2 == 0:
            return s[:half] + s[:half][::-1]
        else:
            return s[:half+1] + s[:half][::-1]

    # Generate palindrome by mirroring left to right
    palindrome = mirror_left_to_right(s)

    if int(palindrome) > num:
        return int(palindrome)

    # Otherwise, increment the middle part and mirror again
    if length % 2 == 0:
        left_half = s[:length//2]
        incremented = str(int(left_half) + 1)
        # If increment causes length increase (e.g. 99 -> 100), handle separately
        if len(incremented) > len(left_half):
            # This means palindrome length increases, e.g. 9999 -> 10001
            return int('1' + ('0' * (length -1)) + '1')
        palindrome = incremented + incremented[::-1]
    else:
        left_half = s[:(length//2)+1]
        incremented = str(int(left_half) + 1)
        if len(incremented) > len(left_half):
            return int('1' + ('0' * (length -1)) + '1')
        palindrome = incremented + incremented[:-1][::-1]

    return int(palindrome)

