def sort_sublists(collection):
    # Determine the type of the input collection to preserve it
    # Sort each subsequence element and return in the same outer collection type
    # For mapping types (dict), the behavior is ambiguous, so we treat only sequences
    # For other iterable types, attempt to reconstruct using type constructor if possible

    # Handle strings separately: they are sequences but sorting subsequences of characters may be confusing
    # Since the input is a collection of subsequences, assume outer is a sequence of subsequences, not a string
    # So if input is a string, treat it as a sequence of characters (which are not subsequences), so likely an error
    # We'll handle sequences and other iterables generically

    # Helper to sort a subsequence element
    def sort_subseq(subseq):
        # subseq is a sequence (e.g. list, tuple, str)
        # We assume subsequence is sortable and iterable
        # For strings, sorting returns list of chars, so convert to string to preserve type
        if isinstance(subseq, str):
            return ''.join(sorted(subseq))
        elif isinstance(subseq, tuple):
            return tuple(sorted(subseq))
        else:
            # For other sequences, convert to list sorted
            return type(subseq)(sorted(subseq))

    # Sort each subsequence element
    sorted_elements = [sort_subseq(subseq) for subseq in collection]

    # Reconstruct outer collection preserving type
    # If input is list, return list
    # If input is tuple, return tuple
    # If input is set, return set (note: sets are unordered, so sorting outer collection doesn't make sense)
    # For other types, try to reconstruct via type constructor, else return list

    typ = type(collection)
    if isinstance(collection, list):
        return sorted_elements
    elif isinstance(collection, tuple):
        return tuple(sorted_elements)
    elif isinstance(collection, set):
        return set(sorted_elements)
    elif hasattr(typ, '__call__'):
        try:
            return typ(sorted_elements)
        except Exception:
            return sorted_elements
    else:
        return sorted_elements

def find_solution(a, b, n):
    # Find integer solutions (x,y) to ax+by = n
    # Return first solution with smallest non-negative x, if any

    # Handle the case a == 0 separately to avoid division by zero
    if a == 0:
        # then by = n => y = n/b if b divides n
        if b == 0:
            return None if n != 0 else (0, 0)  # 0x + 0y = 0 infinite solutions; else no solution
        if n % b == 0:
            return (0, n // b)
        else:
            return None

    # x must be integer >= 0
    x = 0
    while True:
        rhs = n - a * x
        if b == 0:
            # Then equation is a*x = n, check if rhs == 0
            if rhs == 0:
                return (x, 0)
            else:
                return None  # no y can satisfy
        if rhs % b == 0:
            y = rhs // b
            return (x, y)
        x += 1
        # To avoid infinite loop in some cases, stop if x is too large
        # If a > 0 and b > 0 and n >= 0, x can't exceed n//a
        # But since no constraints given, let's just break if x > abs(n)*2+1000 arbitrarily
        if x > abs(n)*2+1000:
            return None

