def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # next palindrome larger than num is 10...01 with length+1 digits
        return num + 2

    # Construct palindrome by mirroring left side to right
    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    odd_length = (length % 2 != 0)
    mid = length // 2

    if odd_length:
        left = s[:mid+1]
    else:
        left = s[:mid]

    palindrome = make_palindrome(left, odd_length)

    if palindrome > num:
        return palindrome

    # Increment the left part and rebuild palindrome
    # Convert left to int, add 1, then back to string with same length (handle carry)
    left_num = int(left) + 1
    left_str = str(left_num)

    # If increment causes length change (like 999 + 1 = 1000)
    if len(left_str) > len(left):
        # For example, 99999 -> increment left becomes 100000, palindrome is 100000000001
        # So return palindrome with length+1: 1 followed by zeros and ending with 1
        return int('1' + ('0' * (length - 1)) + '1')

    palindrome = make_palindrome(left_str, odd_length)
    return palindrome

def sort_sublists(lst):
