    return lst

def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        return None

    x = 0
    while True:
        diff = n - a * x
        if diff < 0:
            return None
        if diff % b == 0:
            y = diff // b
            if y >= 0:
                return (x, y)
        x += 1

def next_power_of_2(n: int) -> int:
    if n <= 0:
        return 1
    power = 1
    while power < n:
        power <<= 1
    return power

def decode_list(encoded):
