def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x] = number of sequences of length i ending with element x
    # Elements range from 1 to m
    if n == 1:
        return m

    dp_prev = [1] * (m + 1)  # for length 1, count=1 for each element
    dp_curr = [0] * (m + 1)

    for length in range(2, n + 1):
        # For each possible current element x,
        # sum over dp_prev[y] where y <= m and x >= 2*y and x <= m
        # i.e. y in [1, x//2]
        prefix_sum = [0] * (m + 1)
        for i in range(1, m + 1):
            prefix_sum[i] = prefix_sum[i - 1] + dp_prev[i]

        for x in range(1, m + 1):
            max_y = x // 2
            if max_y >= 1:
                dp_curr[x] = prefix_sum[max_y]
            else:
                dp_curr[x] = 0

        dp_prev, dp_curr = dp_curr, dp_prev

    return sum(dp_prev[1:])

def even_binomial_Coeff_Sum(n: int) -> int:
    # The sum of binomial coefficients C(n, k) for even k is 2^(n-1) for n >= 1,
    # and 1 for n = 0.
    if n == 0:
        return 1
    return 2**(n-1)

