def dict_depth(d):
    if not isinstance(d, dict) or not d:
        return 1
    return 1 + max(dict_depth(v) for v in d.values() if isinstance(v, dict)) if any(isinstance(v, dict) for v in d.values()) else 1

def min_flip_to_make_string_alternate(s: str) -> int:
    flips_start_0 = 0
    flips_start_1 = 0
    for i, ch in enumerate(s):
        expected_0 = '0' if i % 2 == 0 else '1'
        expected_1 = '1' if i % 2 == 0 else '0'
        if ch != expected_0:
            flips_start_0 += 1
        if ch != expected_1:
            flips_start_1 += 1
    return min(flips_start_0, flips_start_1)

def smallest_missing(arr):
    left, right = 0, len(arr)
    while left < right:
        mid = (left + right) // 2
        if arr[mid] == mid:
            left = mid + 1
        else:
            right = mid
    return left

def highest_Power_of_2(n: int) -> int:
