def find_Max(arr, low, high):
    if low == high:
        return arr[low]
    if high == low + 1:
        return max(arr[low], arr[high])

    mid = (low + high) // 2

    # If mid element is greater than its next element, mid is max
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]
    # If mid element is smaller than its previous element, previous is max
    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]

    # If arr[low] >= arr[mid], max must be in left half
    if arr[low] >= arr[mid]:
        return find_Max(arr, low, mid - 1)
    # Else max must be in right half
    return find_Max(arr, mid + 1, high)

from math import comb

def sum_Of_product(n: int) -> int:
    # Compute sum_{i=0}^n C(n,i)*C(n,n-i) = sum_{i=0}^n C(n,i)^2
    # It is known that sum_{i=0}^n C(n,i)^2 = C(2n, n)
    return comb(2*n, n)

def recur_gcd(a: int, b: int) -> int:
    if b == 0:
        return abs(a)
    return recur_gcd(b, a % b)

